// eslint-disable-next-line no-restricted-imports
import { ExternalEndpointsDefinition, } from '@devvit/protos/types/devvit/plugin/externalendpoints/v1alpha/externalendpoints.js';
import { context } from '@devvit/server';
import { getDevvitConfig } from '@devvit/shared-types/server/get-devvit-config.js';
/**
 * External endpoints plugin which allows apps to be invoked by outside callers.
 */
export class ExternalEndpointsClient {
    /**
     * Get a callback URL for the specified `devvit.json` entry with a short-term
     * token. Eg,
     * `https://wsbapp-2th52-external.devvit.net/external/hello?externalToken=devvit_at_abc123`.
     * Useful for run-as and any ephemeral usage.
     */
    async getCallbackUrl(entry) {
        const rsp = await this._plugin.GetCallbackUrl({ entry }, context.metadata);
        return rsp.callbackUrl;
    }
    /**
     * Get the root `/external/` URL of an install for managed tokens. Eg,
     * `https://wsbapp-2th52-external.devvit.net/external/`. Useful for
     * install-to-install communication.
     */
    async getExternalUrl(opts) {
        const rsp = await this._plugin.GetExternalUrl({ appSlug: opts.appSlug, locationId: opts.locationId }, context.metadata);
        return rsp.externalUrl;
    }
    get _plugin() {
        return getDevvitConfig().use(ExternalEndpointsDefinition);
    }
}
